UITankExplosionGroup=function(game,tankExplosionSounds){Phaser.Group.call(this,game,null);this.tankExplosionSounds=tankExplosionSounds;this.fragmentGroup=this.game.add.group(this);for(var i=0;i<UIConstants.EXPLOSION_FRAGMENT_COUNT;++i){var fragmentSprite=new UIExplosionFragmentSprite(game);this.fragmentGroup.add(fragmentSprite);if(i%2){this.fragmentGroup.add(new UISmokeEmitter(game,fragmentSprite));}}this.emitter=this.add(new UIExplosionEmitter(game));this.exists=false;this.visible=false;};UITankExplosionGroup.prototype=Object.create(Phaser.Group.prototype);UITankExplosionGroup.prototype.constructor=UITankExplosionGroup;UITankExplosionGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);if(this.countLiving()<=1&&this.fragmentGroup.countLiving()==0){this.exists=false;this.visible=false;}};UITankExplosionGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UITankExplosionGroup.prototype.spawn=function(x,y,playerId){this.tankExplosionSounds[Math.floor(Math.random()*UIConstants.TANK_EXPLOSION_AUDIO_COUNT)].play();this.exists=true;this.visible=true;this.emitter.spawn(x,y,QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.TANK_EXPLOSION_SMOKE_COUNT));var numFragments=QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.TANK_EXPLOSION_FRAGMENT_COUNT);for(var i=0;i<numFragments;++i){this.fragmentGroup.children[i].spawn(x,y,playerId);}};UITankExplosionGroup.prototype.retire=function(){this.exists=false;this.visible=false;this.emitter.retire();this.fragmentGroup.callAll('retire');};